import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import api from '../api';
import { isAuthenticated } from '../utils/auth';

export default function BookDetails() {
  const { id } = useParams();
  const [book, setBook] = useState(null);
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');

  async function load() {
    const res = await api.get(`/api/books/${id}`);
    setBook(res.data);
    const rev = await api.get(`/api/reviews/${id}`);
    setReviews(rev.data);
  }

  useEffect(() => { load(); }, [id]);

  async function addReview(e) {
    e.preventDefault();
    if (!isAuthenticated()) { alert('Login to review'); return; }
    try {
      await api.post(`/api/reviews/${id}`, { rating, comment });
      setComment(''); setRating(5); load();
    } catch (err) {
      alert(err?.response?.data?.message || err.message);
    }
  }

  async function addToCart() {
    if (!isAuthenticated()) { alert('Login to add to cart'); return; }
    try {
      await api.post('/api/cart/add', { bookId: id, qty: 1 });
      const cart = JSON.parse(localStorage.getItem('cart') || '[]');
      cart.push({ bookId: id, title: book.title, price: book.price, qty: 1, coverUrl: book.coverUrl });
      localStorage.setItem('cart', JSON.stringify(cart));
      alert('Added to cart');
    } catch (err) {
      alert(err?.response?.data?.message || err.message);
    }
  }

  if (!book) return <div className="text-center py-10 text-gray-600 dark:text-gray-300">Loading...</div>;

  const cover = book.coverUrl
    ? (book.coverUrl.startsWith('/uploads')
        ? `${process.env.REACT_APP_API || 'http://localhost:5000'}${book.coverUrl}`
        : book.coverUrl)
    : 'https://via.placeholder.com/300x420?text=Cover';

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 p-6 md:p-10">
      <div className="bg-white dark:bg-gray-800 shadow-lg rounded-2xl p-6 md:p-10">
        <div className="grid md:grid-cols-3 gap-8">

          {/* --- Left Side: Book Cover --- */}
          <div className="flex justify-center">
            <img
              src={cover}
              alt={book.title}
              className="rounded-lg w-64 h-auto shadow-md hover:scale-105 transition-transform duration-300"
            />
          </div>

          {/* --- Right Side: Book Info --- */}
          <div className="md:col-span-2 space-y-4">
            <h1 className="text-3xl font-bold text-blue-700 dark:text-blue-400">{book.title}</h1>
            <p className="text-gray-600 dark:text-gray-400">By {book.author}</p>

            <p className="mt-2 leading-relaxed">{book.description}</p>

            <div className="mt-4 flex items-center gap-6">
              <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                Rs {book.price}
              </div>
              <div className={`text-sm ${book.stock > 0 ? 'text-green-500' : 'text-red-500'}`}>
                {book.stock > 0 ? 'In stock' : 'Out of stock'}
              </div>
            </div>

            <div className="mt-4 flex gap-3">
              <button
                onClick={addToCart}
                className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg shadow"
              >
                Add to Cart
              </button>

              <button
                onClick={async () => {
                  if (!isAuthenticated()) { alert('Login to wishlist'); return; }
                  await api.post(`/api/wishlist/toggle/${id}`);
                  alert('Wishlist toggled');
                }}
                className="px-5 py-2 rounded-lg border dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                Wishlist
              </button>
            </div>
          </div>
        </div>

        {/* --- Reviews Section --- */}
        <hr className="my-8 border-gray-300 dark:border-gray-700" />

        <h3 className="text-2xl font-semibold text-blue-700 dark:text-blue-400 mb-4">Reviews</h3>
        <div className="space-y-4">
          {reviews.length === 0 ? (
            <p className="text-gray-500 dark:text-gray-400">No reviews yet. Be the first!</p>
          ) : (
            reviews.map((r) => (
              <div key={r._id} className="p-4 bg-gray-100 dark:bg-gray-700 rounded-lg shadow">
                <div className="flex justify-between mb-1">
                  <strong>{r.user?.name || 'User'}</strong>
                  <span className="text-yellow-400">{r.rating}★</span>
                </div>
                <p className="text-sm text-gray-700 dark:text-gray-300">{r.comment}</p>
              </div>
            ))
          )}
        </div>

        {/* --- Review Form --- */}
        <form onSubmit={addReview} className="mt-6 bg-gray-50 dark:bg-gray-800 p-4 rounded-lg shadow space-y-3">
          <h4 className="font-semibold text-lg">Leave a review</h4>

          <select
            value={rating}
            onChange={(e) => setRating(Number(e.target.value))}
            className="p-2 rounded border dark:border-gray-600 dark:bg-gray-700"
          >
            {[5, 4, 3, 2, 1].map((n) => (
              <option key={n} value={n}>
                {n} stars
              </option>
            ))}
          </select>

          <textarea
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            className="w-full p-2 border rounded dark:border-gray-600 dark:bg-gray-700"
            placeholder="Write your thoughts..."
          />

          <button
            type="submit"
            className="px-5 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg"
          >
            Post Review
          </button>
        </form>
      </div>
    </div>
  );
}
